import {evaluate,fixture,followup,parseDocument,STAGES,POLICY_VERSION,bankKey,todayISO,datePlus,approvedBankFor,entityKey,expirySignal,reviewPriority,previewDecision,decisionDelta,validAccount,normalize,taxKey} from './engine.mjs';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',clock:'M12 8v4l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',shield:'M12 3 3 7v5c0 5 9 9 9 9s9-4 9-9V7z M8 12l3 3 5-6',flask:'M9 3h6 M10 3v6l-6 10a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2L14 9V3 M7 15h10',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',down:'M12 3v12 M7 10l5 5 5-5 M5 17v4h14v-4',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',check:'M5 12l4 4L19 6',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',file:'M14 2H5v20h14V7z M14 2v6h5 M8 12h8 M8 16h6',chevron:'M9 5l7 7-7 7',globe:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M2 12h20 M12 2c5 5 5 15 0 20-5-5-5-15 0-20',back:'M19 12H5 M10 7l-5 5 5 5',lock:'M6 10h12v11H6z M8 10V6a4 4 0 0 1 8 0v4',spark:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z',copy:'M9 9h12v12H9z M15 9V3H3v12h6',mail:'M3 5h18v14H3z M3 5l9 8 9-8',x:'M6 6l12 12 M6 18 18 6',bank:'M2 9l10-7 10 7z M4 21h16 M6 10v8 M12 10v8 M18 10v8',filter:'M4 5h16 M7 12h10 M10 19h4',chart:'M4 20V4 M4 20h17 M8 16l4-6 4 3 5-7',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'};
const icon=n=>`<span class="ico" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="${paths[n]||paths.file}"/></svg></span>`;
const countryNames={US:'United States',GB:'United Kingdom',IN:'India'};const flags={US:'🇺🇸',GB:'🇬🇧',IN:'🇮🇳'};
const date=t=>new Date(t).toLocaleDateString('en-IN',{day:'numeric',month:'short',timeZone:'Asia/Kolkata'});
const time=t=>new Date(t).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Kolkata'});
const initials=s=>s.split(' ').slice(0,2).map(x=>x[0]).join('');
const status=s=>`<span class="status ${esc(s)}">${s==='pending'?'Needs review':esc(s)}</span>`;
let records=[],persistent=true,query='',tab='all',country='all',draft=null,running=null,detailTab='checks',modal=null,queueSort='priority',scenarioFilter='all',suite=null,sandbox=null,bankReviewId=null;
const KEY='vendorly-records-v1';
const hash=async s=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s)))].map(x=>x.toString(16).padStart(2,'0')).join('');
function save(){try{localStorage.setItem(KEY,JSON.stringify(records));}catch{persistent=false;toast('Storage is unavailable. Export your records before leaving.');}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4200);}
const go=route=>{if(location.hash===`#${route}`)render();else location.hash=route;};
const route=()=>location.hash.slice(1)||'overview';
function download(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
const button=(text,action,ico='plus',secondary=false)=>`<button class="button ${secondary?'secondary':''}" data-action="${action}">${icon(ico)}${text}</button>`;
async function seed(){
 const configs=[['Lumen Creative LLC','happy','US'],['Juniper Packaging LLC','missing','US'],['Fern Analytics Ltd','expired','GB'],['Cobalt Freight LLC','mismatch','US'],['Evergreen Systems LLC','happy','US'],['Mira Technologies Pvt Ltd','happy','IN'],['Olive & Oak Ltd','happy','GB'],['Aster Supply LLC','missing','US']];
 const all=[];
 for(let i=0;i<configs.length;i++){const [name,kind,c]=configs[i];const v=fixture(kind);v.legalName=name;v.email=name.split(' ')[0].toLowerCase()+'@vendor.example';v.accountName=kind==='mismatch'?'Daniel Brooks':name;v.country=c;v.id='VND-'+String(1008-i);v.sample=true;v.createdAt=new Date(Date.now()-i*86400000-3600000).toISOString();v.updatedAt=v.createdAt;v.taxId=c==='IN'?'27AAPFU0939F1ZV':kind==='expired'?'GB12345':c==='GB'?'GB987654321':`${81-i}-3276195`;v.account=i===0?'6118342096':c==='GB'?String(39127643+i):c==='IN'?'103847261903':`${7200000000+i*213589}`;v.routing=c==='GB'?'200000':c==='IN'?'HDFC0001234':'021000021';v.bankName=c==='GB'?'Barclays':c==='IN'?'HDFC Bank':'Chase Bank';v.accountLast4=v.account.slice(-4);v.accountFormatValid=validAccount(v.account,v.country);v.bankFingerprint=await hash(bankKey(v));v.documents=v.documents.map(d=>({...d,name:name.split(' ')[0].toLowerCase()+'-'+d.type+'.json',legalName:name,taxId:kind==='expired'?'GB123456789':v.taxId,accountLast4:v.accountLast4}));if(i===4)v.documents.find(d=>d.type==='compliance').expiresAt=datePlus(todayISO(),14);v.result=evaluate(v,all);if(v.result.status==='approved')v.approvedBankFingerprint=v.bankFingerprint;v.runs=[{at:v.createdAt,status:v.result.status,checks:v.result.checks,policy:POLICY_VERSION,duration:0,sample:true}];delete v.account;all.push(v);}
 records=all;save();
}
function counts(){return {all:records.length,pending:records.filter(v=>v.result.status==='pending').length,approved:records.filter(v=>v.result.status==='approved').length,rejected:records.filter(v=>v.result.status==='rejected').length};}
const navItems=[['overview','grid','Overview'],['vendors','users','All vendors'],['triage','spark','Action center'],['runs','clock','Activity log'],['policies','shield','Validation rules'],['lab','flask','Scenario lab']];
function shell(body){const r=route().split('/')[0],active=r==='detail'||r==='new'?'vendors':r;const c=counts();return `<div class="shell"><aside class="sidebar"><a class="brand" href="#overview"><span class="brandmark"><i></i><i></i><i></i><i></i></span>vendorly<span style="color:#91ad6b;font-size:26px">.</span></a><div class="workspace"><span class="square">AC</span><div><strong>Acme workspace</strong><small>Procurement operations</small></div><span style="margin-left:auto;color:#7a968b">⌄</span></div><p class="nav-label">Workspace</p><nav class="nav">${navItems.map(([id,ico,label])=>`<button class="${active===id?'active':''}" data-go="${id}">${icon(ico)}${label}${id==='vendors'?`<span class="count">${c.all}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="help-box"><span class="sparkle">✧</span><h4>A little less back-and-forth.</h4><p>Clear checks. Better decisions.<br>Happier vendor relationships.</p><button data-go="lab">Explore the scenario lab <span style="float:right">↗</span></button></div><div class="sidebar-foot"><span class="avatar">AL</span><div>Alex Lee<small>Workspace owner</small></div><span style="margin-left:auto">⌄</span></div></div></aside><main class="main"><header class="topbar"><div class="mobile-brand">vendorly<span style="color:#87a654">.</span></div><div class="breadcrumbs">Workspace <span>/</span><strong>${({overview:'Overview',vendors:'All vendors',runs:'Activity log',policies:'Validation rules',lab:'Scenario lab',triage:'Action center',detail:'Vendor details',new:'New submission'})[r]||'Overview'}</strong></div><div class="top-actions"><span class="date">${new Date().toLocaleDateString('en-IN',{day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Kolkata'})}</span><span class="tag">Local workspace</span><button class="icon-button" data-action="notifications" aria-label="Review queue">${icon('bell')}</button><span class="avatar">AL</span></div></header><div class="content">${!persistent?'<div class="banner warning">Browser storage is unavailable. Export records to keep your work.</div>':''}${body}</div></main><nav class="mobile-nav" aria-label="Main navigation">${navItems.map(([id,ico,label])=>`<button data-go="${id}" class="${active===id?'active':''}">${icon(ico)}${id==='policies'?'Rules':id==='runs'?'Activity':id==='lab'?'Lab':id==='triage'?'Actions':label}</button>`).join('')}</nav></div>${modalView()}`;}
function pageHead(title,sub,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p class="sub">${sub}</p></div><div class="toolbar">${actions}</div></div>`;}
function metric(label,value,note,ico){return `<div class="metric"><div class="metric-top">${label}${icon(ico)}</div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></div>`;}
function table(){const rows=records.filter(v=>(tab==='all'||v.result.status===tab)&&(country==='all'||v.country===country)&&[v.legalName,v.taxId,v.id,v.email].some(s=>s.toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>queueSort==='priority'?reviewPriority(b).rank-reviewPriority(a).rank||new Date(a.createdAt)-new Date(b.createdAt):new Date(b.updatedAt)-new Date(a.updatedAt));return `<section class="panel"><div class="panel-head"><div><h2>Vendor workspace</h2><p>Every submission, one clear next step.</p></div><button class="button text small" data-action="export-csv">${icon('down')}Export</button></div><div class="tabs" role="tablist" aria-label="Vendor status">${[['all','All vendors'],['pending','Needs review'],['approved','Approved'],['rejected','Rejected']].map(([key,label])=>`<button role="tab" aria-selected="${tab===key}" class="${tab===key?'active':''}" data-tab="${key}">${label}<span class="pill">${counts()[key]}</span></button>`).join('')}</div><div class="table-tools"><label class="search">${icon('search')}<input id="vendor-search" type="search" placeholder="Search name, tax ID or reference…" aria-label="Search vendors" value="${esc(query)}"></label><label class="visually-hidden" for="country-filter">Filter by country</label><select id="country-filter" class="filter-select"><option value="all">All countries</option>${Object.entries(countryNames).map(([k,v])=>`<option ${country===k?'selected':''} value="${k}">${v}</option>`).join('')}</select><label class="visually-hidden" for="queue-sort">Sort vendors</label><select id="queue-sort" class="filter-select"><option value="priority" ${queueSort==='priority'?'selected':''}>Priority first</option><option value="recent" ${queueSort==='recent'?'selected':''}>Recently checked</option></select></div><div class="table-wrap vendor-table-wrap"><table><thead><tr><th>Vendor name</th><th>Country</th><th>Submitted</th><th>Checks passed</th><th>Status</th><th><span class="visually-hidden">View</span></th></tr></thead><tbody>${rows.map(v=>`<tr data-id="${esc(v.id)}"><td><div class="vendor-cell"><span class="vendor-symbol" style="${v.result.status==='rejected'?'background:#f5e9e2;color:#a0826e':''}">${esc(initials(v.legalName))}</span><div><strong><button data-detail="${esc(v.id)}" style="padding:0;text-align:left;font:inherit">${esc(v.legalName)}</button></strong><small>${esc(v.category||'Professional services')}${v.sample?'<span class="badge-demo">SAMPLE</span>':''}</small></div></div></td><td>${flags[v.country]||'◌'} &nbsp;${esc(v.country)}</td><td>${date(v.createdAt)}</td><td><div class="score"><span class="score-track"><i class="${v.result.passed<v.result.total?'warn':''}" style="width:${v.result.passed/v.result.total*100}%"></i></span>${v.result.passed}/${v.result.total}</div></td><td>${status(v.result.status)}${reviewPriority(v).tier==='urgent'?'<small class="priority-mark">Priority review</small>':''}</td><td><button class="chevron" data-detail="${esc(v.id)}" aria-label="View ${esc(v.legalName)}">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty">'+icon('search')+'<h3>No vendors found</h3><p>Try another search or add a new submission.</p></div>':''}</div><div class="table-foot"><span>Showing ${rows.length} of ${records.length} vendors</span><span>Saved on this device</span></div></section>`;}
function liveDemoBanner(){
 const demoCases=[
  {kind:'happy',title:'Happy Path',vendor:'Atlas Studio LLC (US)',outcome:'approved',tag:'Happy Path',desc:'Complete submission, valid US EIN, matching bank letter, valid compliance certificate.'},
  {kind:'mismatch',title:'Beneficiary Name Mismatch',vendor:'Cobalt Freight LLC (US)',outcome:'rejected',tag:'Edge Case 1',desc:'Bank account belongs to an unrelated individual (Daniel Brooks). Flags payment fraud.'},
  {kind:'missing',title:'Missing Evidence',vendor:'Juniper Packaging LLC (US)',outcome:'pending',tag:'Edge Case 2',desc:'Bank & compliance evidence missing. Automatically drafts vendor remediation follow-up.'},
  {kind:'bankchange',title:'Approved Bank Change Hold',vendor:'Lumen Creative LLC (US)',outcome:'pending',tag:'Edge Case 3',desc:'Previously approved vendor requests new bank details. Requires reviewer attestation.'},
  {kind:'collision',title:'Shared Account Collision',vendor:'Northstar Consulting LLC (US)',outcome:'rejected',tag:'Edge Case 4',desc:'Shares bank account with another entity (Lumen Creative). Cross-reference catches collision.'}
 ];
 return `<section class="live-demo-banner"><div class="demo-header"><div><h2>${icon('spark')} Interactive Live Demo (PS-2)</h2><p>Run real-time automated onboarding checks from submission to decision. Click any scenario below to watch the 5 stages execute live:</p></div><button class="button small secondary" data-action="new">${icon('plus')} Custom Vendor Intake</button></div><div class="demo-cards-grid">${demoCases.map(c=>`<div class="demo-card"><div class="card-head"><span class="tag ${c.tag==='Happy Path'?'happy':'edge'}">${c.tag}</span>${status(c.outcome)}</div><h3>${esc(c.title)}</h3><p><strong>${esc(c.vendor)}</strong><br>${esc(c.desc)}</p><button class="run-btn" data-run-demo="${c.kind}"><svg viewBox="0 0 24 24" width="14" height="14" fill="currentColor"><path d="M8 5v14l11-7z"/></svg> Run Live Demo</button></div>`).join('')}</div></section>`;
}
function overview(all=false){const c=counts(),pending=triageItems().slice(0,3).map(x=>x.vendor);return pageHead(all?'All vendors':'Onboarding overview',all?'Manage submissions, review evidence, and keep things moving.':'A little clarity for every vendor. A little more time for you.',button('New submission','new'))+(!all?liveDemoBanner():'')+`<div class="metrics">${metric('Total vendors',c.all,'Across your workspace','users')}${metric('Approved',c.approved,`<span>${c.all?Math.round(c.approved/c.all*100):0}%</span> of all submissions`,'check')}${metric('Needs review',c.pending,'A few details to work through','clock')}${metric('Rejected',c.rejected,'Payment identity risk flagged','shield')}</div><div class="${all?'':'dashboard-grid'}"><div>${all?'':watchSummary()}${table()}</div>${all?'':`<div class="side-stack"><section class="panel attention"><h3>Priority review <span>${triageItems().length} actions</span></h3><p>Blocking findings and time-sensitive evidence first.</p>${pending.length?pending.map(v=>`<button class="attention-item" data-detail="${v.id}"><div class="item-title">${esc(v.legalName)}<span>↗</span></div><small>${esc(reviewPriority(v).reason)}</small><span class="mini-tag">${reviewPriority(v).tier==='urgent'?'Priority review':'Action needed'}</span></button>`).join(''):'<p>All caught up. Your review queue is clear.</p>'}</section><section class="panel insight"><h3>${icon('spark')} A smarter second look</h3><p>A familiar bank account under a different company? We connect the dots before a payment does.</p><button data-go="triage">Open action center ${icon('arrow')}</button></section></div>`}</div><div class="bottom-note"><span>${icon('lock')} Your data stays in this browser · Sample records are labeled</span><span>Thoughtful onboarding, from start to finish.</span></div>`;}
const field=(key,label,value='',hint='',type='text',full=false)=>`<div class="field ${full?'full':''}"><label for="f-${key}">${label}</label><input id="f-${key}" name="${key}" type="${type}" value="${esc(value)}" ${key==='email'?'autocomplete="email"':''} ${['legalName','email','country','address','taxId','bankName','accountName','routing'].includes(key)?'required':''} ${key==='account'&&!draft?.bankFingerprint?'required':''}>${hint?`<small class="hint">${hint}</small>`:''}</div>`;
function newForm(){const v=draft||{};return pageHead(v.id?'Update & recheck':'Let’s meet your next vendor',v.id?`${esc(v.id)} · Corrections create a new run and preserve the audit trail.`:'Enter the details. Add the evidence. We’ll connect the dots.',button('Back to vendors','vendors','back',true))+`<div class="form-layout"><form id="submission-form">${v.id?'<div class="banner">'+icon('bank')+'Changing a previously approved payment account creates a review hold, even when the new documents match.</div>':''}<div class="panel form-panel"><div class="section-title"><span class="step-num">01</span><div><h3>Company details</h3><p>The essentials behind a good partnership.</p></div></div><div class="fields">${field('legalName','Legal company name',v.legalName)}${field('contactName','Contact name',v.contactName)}${field('email','Contact email',v.email,'A follow-up draft will be addressed here.','email')}<div class="field"><label for="f-country">Registration country</label><select id="f-country" name="country">${Object.entries(countryNames).map(([k,n])=>`<option value="${k}" ${(v.country||'US')===k?'selected':''}>${flags[k]} ${n}</option>`).join('')}</select></div>${field('taxId','Tax registration ID',v.taxId,'US: EIN · UK: VAT · India: GSTIN (format + checksum)')}<div class="field"><label for="f-category">Service category</label><select id="f-category" name="category">${['Professional services','Design & creative','Technology','Logistics','Goods & supplies','Other'].map(c=>`<option ${v.category===c?'selected':''}>${c}</option>`).join('')}</select></div>${field('address','Registered address',v.address,'Include city, state and postal code.','text',true)}</div></div><div class="panel form-panel"><div class="section-title"><span class="step-num">02</span><div><h3>Payment details</h3><p>Make sure the right business gets paid.</p></div></div><div class="fields">${field('bankName','Bank name',v.bankName)}${field('accountName','Account holder name',v.accountName,'Use the name exactly as it appears at the bank.')}${field('account',v.bankFingerprint?'New account number (optional)':'Account number',v.account,v.bankFingerprint?`Current account: •••• ${v.accountLast4}. Leave blank to keep it.`:'Stored as a SHA-256 fingerprint and last four digits.','text')}${field('routing','Routing code / sort code / IFSC',v.routing,'US: 9 digits · UK: 6 digits · India: 11-character IFSC')}</div></div><div class="panel form-panel"><div class="section-title"><span class="step-num">03</span><div><h3>Supporting evidence</h3><p>Readable details turn submissions into decisions.</p></div></div><div class="banner">${icon('info')}Upload TXT or JSON documents (up to 1 MB each). Other formats are kept as unreadable evidence and require manual review. Download the template to see the expected fields.</div>${[['tax','Tax registration','Registered name and tax ID'],['bank','Bank ownership letter','Registered name and account ending'],['compliance','Compliance declaration','Registered name and expiry date']].map(([type,label,desc])=>{const d=v.documents?.find(d=>d.type===type);return `<div class="doc-slot" id="evidence-${type}"><div class="doc-slot-head">${icon('file')}<div>${label}<small>${d?esc(d.name)+(d.unsupported?' · Needs manual review':' · Ready to check'):desc}</small></div></div><div class="doc-controls"><label><span class="visually-hidden">Upload ${label}</span><input type="file" data-doc="${type}" accept=".json,.txt,.pdf,.png,.jpg,.jpeg"></label><button type="button" data-template-doc="${type}">Template ↓</button>${d?`<button type="button" data-remove-doc="${type}">Remove</button>`:''}</div></div>`;}).join('')}<button type="button" class="button text small" data-action="templates">${icon('down')}Download document templates</button></div><div class="panel form-panel"><div class="field"><label for="f-notes">Anything else? <span>Optional</span></label><textarea id="f-notes" name="notes" placeholder="A trading name, shared services arrangement, or context for the reviewer…">${esc(v.notes||'')}</textarea></div></div><div class="form-actions"><p class="sub">Checks run locally.<br>No messages are sent automatically.</p><button type="submit" class="button">${icon('shield')}${v.id?'Save & recheck':'Run onboarding checks'}</button></div></form><aside class="panel form-help"><p class="eyebrow">A CLEARER WAY FORWARD</p><h3>What happens next?</h3><ul><li>Check company and tax details.</li><li>Cross-check bank identity.</li><li>Read and compare document fields.</li><li>Return a reasoned decision.</li><li>Prepare a specific follow-up.</li></ul><div class="divider"></div><h3>Start with a real example</h3><p>Load a complete submission, then change any field to see how the decision responds.</p><button class="button secondary small" data-fixture="happy">${icon('plus')}Use a sample vendor</button><div class="divider"></div><h3>Document format</h3><p>Use one document per type. For example, a bank letter:</p><pre class="mono">{\n  "legalName": "Atlas Studio LLC",\n  "accountLast4": "3058"\n}</pre><p>These are consistency checks, not live tax registration, sanctions screening, or bank ownership verification.</p></aside></div>`;}
function stagesView(v,live=false){return STAGES.map((name,i)=>{const complete=!live||i<running.stage,active=live&&i===running.stage;const cc=v.result?.checks?.filter(c=>c.stage===i)||[];return `<section class="run-stage"><div class="stage-header"><span class="stage-circle ${active?'live':''}">${complete?'✓':active?'':i+1}</span><strong>${name}</strong><small>${complete?(i===4?'Complete':`${cc.length} checks`):active?'Running…':'Waiting'}</small></div>${complete?cc.map(c=>`<div class="check-row ${c.state}"><span class="check-sign">${c.state==='pass'?'✓':c.state==='reject'?'×':'!'}</span><div><strong>${esc(c.label)}</strong><p>${esc(c.reason)}</p>${c.state!=='pass'?`<p class="action">Next step: ${esc(c.action)}</p>`:''}</div></div>`).join(''):''}${i===4&&complete?`<div class="check-row"><span class="check-sign">✓</span><div><strong>Decision recorded · ${esc(v.result.policy||POLICY_VERSION)}</strong><p>${esc(v.result.summary)} A follow-up draft and downloadable audit report are ready.</p></div></div>`:''}</section>`;}).join('');}
function detail(id){const v=records.find(x=>x.id===id);if(!v)return pageHead('Vendor not found','This reference is not in your local workspace.',button('View all vendors','vendors','back',true));return pageHead(esc(v.legalName),`${esc(v.id)} · ${countryNames[v.country]} · ${v.sample?'Sample submission':'Submitted '+date(v.createdAt)}`,`${button('← Back to Demo','overview','back',true)}${button('Export report','export-report','down',true)}${button('Update & recheck','edit','plus')}`)+`<div class="detail-grid"><aside class="panel detail-summary"><span class="vendor-symbol">${esc(initials(v.legalName))}</span><h2>${esc(v.legalName)}</h2>${status(v.result.status)}<dl class="data-list">${[['Contact',v.contactName||'Not provided'],['Email',v.email],['Tax ID',v.taxId],['Registration country',countryNames[v.country]],['Address',v.address],['Account holder',v.accountName],['Bank',v.bankName],['Account ending','•••• '+v.accountLast4],['Routing code',v.routing],['Category',v.category],['Last checked',time(v.updatedAt)+' IST']].map(([k,x])=>`<dt>${k}</dt><dd>${esc(x)}</dd>`).join('')}</dl>${v.notes?`<dl class="data-list"><dt>Reviewer context</dt><dd>${esc(v.notes)}</dd></dl>`:''}</aside><div><section class="panel decision"><div class="decision-head"><h2>${v.result.status==='approved'?'A clear path forward.':v.result.status==='pending'?'A few details need attention.':'Let’s pause before payment.'}</h2>${status(v.result.status)}</div><p>${esc(v.result.summary)}</p><div class="run-progress">${Array.from({length:v.result.total},(_,i)=>`<i class="${i<v.result.passed?'done':''}"></i>`).join('')}</div><div class="progress-note">${v.result.passed} of ${v.result.total} checks passed · Policy ${esc(v.result.policy||POLICY_VERSION)} · ${v.runs.length} run${v.runs.length>1?'s':''}</div>${v.result.status!=='approved'?`<div style="margin-top:16px;padding:12px 14px;background:#fbfdf9;border:1px solid #dce5d0;border-radius:8px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px"><span style="font-size:12px;color:#4f6b48">${icon('mail')} <strong>Vendor Follow-up Draft Prepared:</strong> ${v.result.actions.length} action item${v.result.actions.length===1?'':'s'} communicated.</span><button class="button small secondary" data-detail-tab="followup">${icon('mail')} View & Copy Follow-up Email</button></div>`:''}</section>${v.result.policy!==POLICY_VERSION?'<div class="banner warning">'+icon('shield')+'Policy '+POLICY_VERSION+' adds new checks. Existing results are preserved until you recheck this vendor. <button class="inline-link" data-action="recheck">Recheck now →</button></div>':''}${v.sample?'<div class="banner">'+icon('flask')+'This is sample data. Update and recheck to run the engine on these inputs.</div>':''}<div class="detail-tabs tabs" role="tablist">${[['checks','Checks & reasoning'],['evidence','Evidence'],['followup','Vendor follow-up'],['sandbox','What-if preview'],['history','Run history']].map(([k,l])=>`<button role="tab" aria-selected="${detailTab===k}" class="${detailTab===k?'active':''}" data-detail-tab="${k}">${l}</button>`).join('')}</div>${detailTab==='checks'?`<section class="panel form-panel"><h3>Every check, explained</h3>${bankGuardUI(v)}${stagesView(v)}</section>`:detailTab==='evidence'?evidence(v):detailTab==='followup'?`<section class="panel form-panel"><div class="panel-head" style="padding:0 0 20px"><div><h3>A specific, useful follow-up</h3><p>Draft only · review before sharing through a secure channel.</p></div></div><div class="message">${esc(followup(v))}</div><div class="toolbar" style="margin-top:18px">${button('Copy draft','copy-followup','copy',true)}${button('Download draft','download-followup','down',true)}</div></section>`:detailTab==='sandbox'?sandboxView(v):historyView(v)}</div></div>`;}
function evidence(v){
 const docMeta={
  tax:{label:'Tax Registration Evidence',icon:'file',badge:'Tax Document'},
  bank:{label:'Bank Ownership Proof',icon:'bank',badge:'Bank Letter'},
  compliance:{label:'Compliance Declaration',icon:'shield',badge:'Compliance Cert'}
 };
 const docs=v.documents||[];
 if(!docs.length)return '<div class="empty">No evidence has been supplied.</div>';
 return `<div class="banner">${icon('info')}<div><strong>Automated Evidence Cross-Referencing</strong><p style="margin:2px 0 0;font-size:11px">Extracted fields from vendor documents are compared against submission inputs. Full numbers and raw files are discarded to protect privacy.</p></div></div><div class="evidence-grid">${docs.map(d=>{
  const meta=docMeta[d.type]||{label:'Supporting Document',icon:'file',badge:'Document'};
  const isMismatch=(d.type==='bank'&&v.accountName&&normalize(d.legalName)!==normalize(v.accountName))||(d.type==='tax'&&v.taxId&&d.taxId&&taxKey(d.taxId,v.country)!==taxKey(v.taxId,v.country))||(d.type==='compliance'&&d.expiresAt&&d.expiresAt<todayISO());
  return `<section class="panel evidence-card enhanced-evidence-card"><div class="evidence-card-header"><div class="evidence-title-group"><span class="evidence-type-icon">${icon(meta.icon)}</span><div><div style="display:flex;align-items:center;gap:8px"><span class="badge-evidence-type">${meta.badge}</span><span class="evidence-filename">${esc(d.name)}</span></div><h3 style="margin-top:4px">${meta.label}</h3></div></div><span class="status ${d.unsupported?'pending':isMismatch?'rejected':'approved'}">${d.unsupported?'Unreadable':isMismatch?'Discrepancy':'Verified'}</span></div>${d.unsupported?`<div class="evidence-unsupported-note"><p><strong>Unreadable format:</strong> OCR is not connected for this file. Provide structured UTF-8 TXT/JSON or route for specialist review.</p></div>`:`<div class="evidence-comparison-table table-wrap"><table><thead><tr><th>Field Verified</th><th>Extracted from Document</th><th>Submission Form Value</th><th>Cross-Check</th></tr></thead><tbody><tr><td><strong>Legal Entity Name</strong></td><td><code>${esc(d.legalName||'Not found')}</code></td><td>${esc(v.legalName)}</td><td><span class="status ${normalize(d.legalName)===normalize(v.legalName)?'approved':'rejected'}">${normalize(d.legalName)===normalize(v.legalName)?'✓ Match':'Mismatch'}</span></td></tr>${d.type==='tax'?`<tr><td><strong>Tax Registration ID</strong></td><td><code>${esc(d.taxId||'Not found')}</code></td><td>${esc(v.taxId)}</td><td><span class="status ${taxKey(d.taxId,v.country)===taxKey(v.taxId,v.country)?'approved':'rejected'}">${taxKey(d.taxId,v.country)===taxKey(v.taxId,v.country)?'✓ Match':'Mismatch'}</span></td></tr>`:''}${d.type==='bank'?`<tr><td><strong>Account Ending</strong></td><td><code>•••• ${esc(d.accountLast4||'N/A')}</code></td><td>•••• ${esc(v.accountLast4||(v.account?v.account.slice(-4):'N/A'))}</td><td><span class="status ${d.accountLast4===(v.accountLast4||(v.account?v.account.slice(-4):''))?'approved':'rejected'}">${d.accountLast4===(v.accountLast4||(v.account?v.account.slice(-4):''))?'✓ Match':'Mismatch'}</span></td></tr><tr><td><strong>Payment Beneficiary</strong></td><td><code>${esc(d.legalName)}</code></td><td><span style="color:#b06c5c;font-weight:600">${esc(v.accountName||'N/A')}</span></td><td><span class="status ${normalize(d.legalName)===normalize(v.accountName)?'approved':'rejected'}">${normalize(d.legalName)===normalize(v.accountName)?'✓ Match':'× Conflict'}</span></td></tr>`:''}${d.type==='compliance'?`<tr><td><strong>Certificate Expiry</strong></td><td><code>${esc(d.expiresAt||'Not specified')}</code></td><td>Current Date (${todayISO()})</td><td><span class="status ${d.expiresAt&&d.expiresAt>=todayISO()?'approved':'pending'}">${d.expiresAt&&d.expiresAt>=todayISO()?'✓ Active':'Expired'}</span></td></tr>`:''}</tbody></table></div>${d.type==='bank'&&normalize(d.legalName)!==normalize(v.accountName)?`<div class="evidence-alert">${icon('shield')} <strong>Payment Risk Alert:</strong> Document confirms ownership by <em>${esc(d.legalName)}</em>, but payout was requested to <em>${esc(v.accountName)}</em>. This flagged conflict prevents unauthorized account redirection.</div>`:''}`}</section>`;
 }).join('')}</div>`;
}
function historyView(v){return `<section class="panel form-panel"><h3>A record of every decision</h3>${[...v.runs].reverse().map((r,i)=>{const prev=v.runs[v.runs.length-2-i];const changes=prev?r.checks.filter(c=>prev.checks.find(x=>x.id===c.id)?.state!==c.state):[];return `<div class="activity-event">${icon('clock')}<div><strong>Run ${v.runs.length-i} · ${r.status==='pending'?'Needs review':r.status[0].toUpperCase()+r.status.slice(1)}</strong><p>${r.checks.filter(c=>c.state==='pass').length}/${r.checks.length} checks passed · Policy ${esc(r.policy)}${r.sample?' · Sample result':` · ${r.duration} ms`}</p>${changes.length?`<p>Changed: ${changes.map(c=>esc(c.label)+' → '+(c.state==='pass'?'passed':c.state)).join('; ')}</p>`:''}${r.bankVerification?'<p class="review-note">Trusted-channel confirmation by '+esc(r.bankVerification.reviewer)+': '+esc(r.bankVerification.note)+'</p>':''}<time>${time(r.at)} IST</time><button class="button text small" data-run-report="${v.id}:${v.runs.length-1-i}">Download this run ${icon('down')}</button></div></div>`;}).join('')}</section>`;}
function liveView(){const v=running.vendor;return pageHead('A closer look, in real time.',`${esc(v.legalName)} · Checks execute in your browser.`)+`<div class="panel form-panel" style="max-width:820px;margin:auto"><div class="decision-head"><h2>Onboarding in progress</h2><span class="status running">Running</span></div><div class="run-progress">${STAGES.map((_,i)=>`<i class="${i<running.stage?'done':''}"></i>`).join('')}</div>${stagesView(v,true)}</div>`;}
const scenarios=[
 ['happy','The complete submission','A consistent name, valid payment details, and current evidence. The happy path, from start to finish.','approved','✓','baseline',[]],
 ['missing','The missing pieces','Bank and compliance evidence are absent. Ask for exactly what is missing.','pending','◫','evidence',['doc-bank','doc-compliance']],
 ['mismatch','A different beneficiary','Complete documents, but the bank account belongs to an unrelated person.','rejected','↯','payment',['beneficiary']],
 ['expired','The cross-border mix-up','Malformed UK VAT, conflicting tax evidence, and an expired declaration.','pending','◷','tax',['tax','doc-tax','doc-compliance']],
 ['collision','One account. Two companies.','A new company shares the account of Lumen Creative. Surface the connection before payment.','rejected','⇄','payment',['collision']],
 ['bankchange','A new account after approval','An approved vendor requests new payment details. Keep a hold until a reviewer records independent contact verification.','pending','↗','payment',['bank-change']],
 ['lookalike','A name that only looks right','A Cyrillic letter appears inside an otherwise Latin company name, consistently across all evidence. Ask for the registered spelling.','pending','Aa','identity',['script']],
 ['wrongdoc','An invoice in the tax slot','The fields match, but the evidence declares itself an invoice. The correct document still needs to be supplied.','pending','▤','evidence',['doc-tax']],
 ['checksum','The almost-valid GSTIN','Correct length and format, matching evidence, but an incorrect check digit. Catch the transcription error.','pending','#','tax',['tax-integrity']],
 ['duplicate','Same tax identity, fresh submission','A differently named intake reuses an existing company’s tax ID. Review the existing vendor instead of creating a duplicate.','pending','⧉','identity',['entity']]
];
function lab(){
 const shown=scenarios.filter(x=>scenarioFilter==='all'||x[5]===scenarioFilter);
 return pageHead('Challenge every decision.','One happy path. Nine edge cases. Real checks, reproducible results.',`<button class="button" data-action="run-suite" ${suite?.running?'disabled':''}>${icon('flask')}${suite?.running?'Testing…':'Run all 10 scenarios'}</button>`)+
 `<div class="banner">${icon('info')}The test suite uses isolated sample history and never adds vendors to your workspace. Editable bank-change, collision, and duplicate scenarios use existing workspace records.</div>${suiteView()}
 <div class="scenario-filters tabs" role="tablist" aria-label="Scenario category">${[['all','All scenarios'],['payment','Payment'],['identity','Identity'],['evidence','Evidence'],['tax','Tax'],['baseline','Happy path']].map(([id,label])=>`<button role="tab" aria-selected="${scenarioFilter===id}" class="${scenarioFilter===id?'active':''}" data-scenario-filter="${id}">${label}</button>`).join('')}</div>
 <div class="scenario-grid">${shown.map(([key,title,description,expected,symbol,category])=>`<section class="panel scenario"><div class="scenario-meta"><span class="scenario-icon">${symbol}</span><span class="eyebrow">${category}</span></div><span class="expected-label">Expected outcome</span>${status(expected)}<h3>${title}</h3><p>${description}</p><button class="button secondary small" data-fixture="${key}">Load editable scenario ${icon('arrow')}</button></section>`).join('')}</div>
 <section class="panel bring-own"><div><h3>Have a different edge case?</h3><p class="sub">Import a structured submission or start with a blank form.</p></div><div class="toolbar">${button('Import JSON','import','file',true)}${button('Start fresh','new','plus',true)}</div></section>`;
}
function policies(){return pageHead('Good decisions have clear rules.','Policy '+POLICY_VERSION+' · Deterministic, transparent, and consistent for every submission.',button('Export workspace','backup','down',true))+`<div class="banner">${icon('shield')}Approved means the configured consistency checks passed. This prototype does not verify live tax registration, document authenticity, sanctions, or ownership with a bank.</div><section class="panel">${[
 ['file','Completeness & contact','Company, contact, registered address, tax registration, and payment fields must be present. Malformed email addresses need correction.','pending'],
 ['globe','Country-specific tax formats','US: EIN (9 digits). UK: VAT (9 digits with optional GB prefix). India: GSTIN structure, state code, and base-36 check digit. UK GB prefixes are normalized for duplicate detection. No live tax registry lookup is performed.','pending'],
 ['users','Identity consistency','Legal name and beneficiary are normalized for punctuation and common entity suffixes. Partial matches require review; unrelated names are blocking findings.','rejected'],
 ['bank','Payment detail structure','US ABA routing checksum and 8–17 digit accounts; UK 6-digit sort code and 8-digit accounts; India IFSC structure and 9–18 digit accounts.','pending'],
 ['shield','Duplicate company & shared account','An existing tax ID requires review. A SHA-256 fingerprint of country, routing and account detects a bank account shared by different normalized legal names. The current vendor is excluded on recheck.','rejected'],
 ['file','Evidence & expiry','Tax, bank and compliance evidence must be readable and consistent with the submission. Compliance expiry must be today or later. Unreadable or absent evidence goes to review.','pending'],
 ['bank','Bank change after approval','A changed account fingerprint stays pending until a reviewer records independent contact confirmation. The note is bound to the specific new account and company identity; other blocking findings remain in force.','pending'],
 ['users','Mixed-script identity names','A name mixing Latin with Cyrillic or Greek letters goes to review. This flags possible lookalike characters; it does not declare the vendor fraudulent.','pending'],
 ['file','Document type consistency','An explicit documentType must match the evidence slot. An invoice cannot stand in for tax evidence. Legacy evidence without a declared type still uses field consistency checks.','pending'],
 ['clock','Expiry watch & queue priority','Expiry dates are checked against the current India business date. Documents expiring within 30 days appear in the action center. Queue priority uses visible reasons, not a fraud probability. Old run results remain unchanged until rechecked.','pending'],
 ['chart','Decision precedence','A blocking identity or shared-account finding produces Rejected. Otherwise any unresolved issue produces Pending. Only submissions passing every configured check produce Approved.','approved']
 ].map(([ico,t,p,s])=>`<div class="policy-row">${icon(ico)}<div><h3>${t}</h3><p>${p}</p></div>${status(s)}</div>`).join('')}</section><div class="panel form-panel" style="margin-top:20px"><h3>Your workspace, your data</h3><p class="sub" style="margin:12px 0 20px">Records and extracted document fields are stored in this browser. Full bank account numbers are removed before saving. Export a backup to move records between devices. External verification and email delivery are not connected.</p><div class="toolbar">${button('Export backup','backup','down',true)}${button('Import submissions','import','file',true)}${button('Remove sample data','remove-samples','x',true)}${button('Reset workspace','reset','x',true)}</div></div>`;}
function activity(){const events=records.flatMap(v=>v.runs.map((r,i)=>({v,r,i}))).sort((a,b)=>new Date(b.r.at)-new Date(a.r.at));return pageHead('Every step leaves a trail.','Review run history, decisions, and changes across the workspace.',button('Export workspace','backup','down',true))+`<section class="panel form-panel">${events.map(({v,r,i})=>`<div class="activity-event">${icon('clock')}<div><strong><button style="font:inherit;padding:0" data-detail="${v.id}">${esc(v.legalName)} ↗</button></strong><p>Run ${i+1} · ${r.checks.filter(c=>c.state==='pass').length}/${r.checks.length} checks · ${esc(r.policy)} ${r.sample?'· Sample result':''}</p><time>${time(r.at)} IST</time></div><div style="margin-left:auto">${status(r.status)}</div></div>`).join('')||'<div class="empty"><h3>Your first run starts here.</h3><p>Add a vendor to create a decision trail.</p></div>'}</section>`;}
function modalView(){return modal?`<div class="modal-shade"><section role="dialog" aria-modal="true" aria-labelledby="modal-title" class="modal"><h2 id="modal-title">${modal.title}</h2><p>${modal.text}</p><div class="toolbar"><button class="button secondary" data-action="close-modal">Cancel</button><button class="button" data-action="${modal.confirm}">${modal.label}</button></div></section></div>`:'';}
function render(){const r=route();let body=running?liveView():r==='overview'?overview():r==='vendors'?overview(true):r==='new'?newForm():r==='lab'?lab():r==='triage'?actionCenter():r==='policies'?policies():r==='runs'?activity():r.startsWith('detail/')?detail(r.split('/')[1]):overview();$('#app').innerHTML=shell(body);if(modal)$('#app .modal button')?.focus();}
function captureForm(){const f=$('#submission-form');if(f)draft={...(draft||{}),...Object.fromEntries(new FormData(f).entries())};}
async function loadFile(file,type){captureForm();if(!draft)draft={};if(!draft.documents)draft.documents=[];if(file.size>1024*1024){toast('Please choose a file smaller than 1 MB.');return;}const good=/\.(txt|json)$/i.test(file.name);let doc;try{doc=good?parseDocument(await file.text(),file.name,type):{name:file.name,type,unsupported:true};}catch{toast('Could not read this file. Try a UTF-8 TXT or JSON document.');return;}draft.documents=draft.documents.filter(d=>d.type!==type).concat(doc);render();toast(good?'Document fields loaded. Run checks to compare them.':'This format requires manual review.');}
function safeVendor(v){const out=structuredClone(v);delete out.account;return out;}
async function runSubmission(v){
 const existing=records.find(x=>x.id===v.id);if(!v.account&&existing&&v.country!==existing.country){toast('Enter the account again after changing the bank country.');return;}if(!v.account&&existing&&v.routing.replace(/[\s-]/g,'').toUpperCase()!==existing.routing.replace(/[\s-]/g,'').toUpperCase()){toast('Enter the account again after changing the routing code.');return;}
 const start=performance.now(),now=new Date().toISOString();v.id=v.id||'VND-'+(Math.max(1008,...records.map(r=>Number(r.id.split('-')[1])||1008))+1);v.createdAt=existing?.createdAt||now;v.updatedAt=now;v.sample=false;
 running={vendor:v,stage:0};render();window.scrollTo(0,0);
 try{for(let stage=0;stage<5;stage++){running.stage=stage;render();
  const isInteractive=typeof window!=='undefined'&&!window.navigator?.userAgent?.includes('jsdom');
  if(isInteractive){await new Promise(r=>setTimeout(r,320));}else{await new Promise(requestAnimationFrame);await new Promise(requestAnimationFrame);}
  if(stage===2&&v.account){v.accountFormatValid=validAccount(v.account,v.country);v.bankFingerprint=await hash(bankKey(v));v.accountLast4=v.account.replace(/[\s-]/g,'').slice(-4);}const result=evaluate(v,records);v.result={...result,checks:result.checks.filter(c=>c.stage<=stage)};}
 v.result=evaluate(v,records);v.approvedBankFingerprint=v.result.status==='approved'?v.bankFingerprint:approvedBankFor(existing);const run={at:now,status:v.result.status,checks:v.result.checks,policy:POLICY_VERSION,duration:Math.round(performance.now()-start),sample:false,bankVerification:v.bankVerification||null};run.input=Object.fromEntries(['legalName','country','taxId','accountName','accountLast4','routing','bankFingerprint','accountFormatValid','documents'].map(k=>[k,v[k]]));v.runs=[...(existing?.runs||[]),run];const persisted=safeVendor(v);records=records.filter(x=>x.id!==v.id).concat(persisted);save();draft=null;running=null;sandbox=null;bankReviewId=null;detailTab='checks';go('detail/'+v.id);toast('Checks complete. Decision and follow-up are ready.');}catch(e){running=null;render();toast('The run could not finish. Your input is still available; please try again.');console.error(e);}
}
async function runLiveDemo(kind){
 await loadScenario(kind);
 const v=structuredClone(draft);
 if(!v.bankFingerprint&&!v.account){v.account=v.country==='GB'?'42618059':v.country==='IN'?'104261738059':'7264193058';}
 await runSubmission(v);
}
function getCurrent(){return records.find(v=>v.id===route().split('/')[1]);}
function report(v){return {vendor:safeVendor(v),generatedAt:new Date().toISOString(),verificationScope:'Local consistency checks only. No live registry, sanctions, bank ownership, or document authenticity verification.',followupDraft:followup(v)};}
document.addEventListener('click',async e=>{const el=e.target.closest('button,a,tr[data-id]');if(!el)return;const d=el.dataset;if(d.runDemo){await runLiveDemo(d.runDemo);return;}if(d.go){if(running){toast('Wait for the current run to finish.');return;}go(d.go);return;}if(d.detail||d.id){detailTab='checks';go('detail/'+(d.detail||d.id));return;}if(d.tab){tab=d.tab;render();return;}if(d.detailTab){detailTab=d.detailTab;render();return;}if(d.fixture){loadScenario(d.fixture);return;}if(d.templateDoc){captureForm();const base=draft||{};const type=d.templateDoc;const obj={documentType:type,legalName:base.legalName||'Your legal company name'};if(type==='tax')obj.taxId=base.taxId||'84-3276195';if(type==='bank')obj.accountLast4=base.account?base.account.replace(/\D/g,'').slice(-4):base.accountLast4||'3058';if(type==='compliance')obj.expiresAt='2028-12-31';download(type+'-evidence.json',JSON.stringify(obj,null,2));return;}if(d.removeDoc){captureForm();draft.documents=draft.documents.filter(x=>x.type!==d.removeDoc);render();return;}if(d.runReport){const [id,i]=d.runReport.split(':');const v=records.find(x=>x.id===id);download(`${id}-run-${Number(i)+1}.json`,JSON.stringify({vendorId:id,legalName:v.legalName,run:v.runs[Number(i)]},null,2));return;}
 if(d.scenarioFilter){scenarioFilter=d.scenarioFilter;render();return;}
 const a=d.action;if(!a)return;const v=getCurrent();if(a==='run-suite'){runScenarioSuite();return;}if(a==='export-suite'){download('vendorly-scenario-results.json',JSON.stringify(suite,null,2));return;}if(a==='open-bank-review'){bankReviewId=v.id;render();$('#reviewer-name')?.focus();return;}if(a==='cancel-bank-review'){bankReviewId=null;render();return;}if(a==='recheck'){runSubmission(structuredClone(v));return;}if(a==='recheck-vendor'){const target=records.find(x=>x.id===d.vendor);if(target)runSubmission(structuredClone(target));return;}if(a==='new'){draft={documents:[]};go('new');}else if(['overview','vendors','lab','triage'].includes(a))go(a);else if(a==='review'||a==='notifications'){tab='pending';go('vendors');if(route()==='vendors')render();}else if(a==='edit'){draft=structuredClone(v);go('new');}else if(a==='export-report')download(v.id+'-report.json',JSON.stringify(report(v),null,2));else if(a==='backup')download('vendorly-workspace.json',JSON.stringify({version:1,exportedAt:new Date().toISOString(),records},null,2));else if(a==='export-csv'){const cell=x=>'"'+String(x??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';download('vendorly-vendors.csv',[['Reference','Legal name','Country','Tax ID','Status','Checks passed','Total checks','Last run','Sample'],...records.map(v=>[v.id,v.legalName,v.country,v.taxId,v.result.status,v.result.passed,v.result.total,v.updatedAt,v.sample?'Yes':'No'])].map(row=>row.map(cell).join(',')).join('\r\n'),'text/csv');}else if(a==='copy-followup'){try{await navigator.clipboard.writeText(followup(v));toast('Follow-up draft copied.');}catch{toast('Clipboard unavailable. Download the draft instead.');}}else if(a==='download-followup')download(v.id+'-followup.txt',followup(v),'text/plain');else if(a==='templates'){const base=draft||fixture();download('document-templates.json',JSON.stringify({instructions:'Save each object below as its own JSON file and upload it to the matching document slot. Replace the example values with document evidence.',tax:{legalName:base.legalName||'Your legal company name',taxId:base.taxId||'84-3276195'},bank:{legalName:base.legalName||'Your legal company name',accountLast4:base.account?base.account.replace(/\D/g,'').slice(-4):base.accountLast4||'3058'},compliance:{legalName:base.legalName||'Your legal company name',expiresAt:'2028-12-31'}},null,2));toast('Template downloaded. Save each document as a separate JSON file.');}else if(a==='import')importJSON();else if(a==='close-modal'){modal=null;render();}else if(a==='remove-samples'){modal={title:'Remove the sample vendors?',text:'This removes sample records and their history. Submissions you have run will remain.',label:'Remove samples',confirm:'confirm-samples'};render();}else if(a==='confirm-samples'){records=records.filter(x=>!x.sample);save();modal=null;render();toast('Sample records removed.');}else if(a==='reset'){modal={title:'Reset this workspace?',text:'All local vendor records and run history will be removed, then sample records will be restored. Export a backup first if you need these records.',label:'Reset workspace',confirm:'confirm-reset'};render();}else if(a==='confirm-reset'){await seed();modal=null;draft=null;go('overview');render();toast('Workspace reset with fresh sample data.');}});
function importJSON(){const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{const file=input.files[0];if(!file)return;if(file.size>5*1024*1024){toast('Choose a JSON file smaller than 5 MB.');return;}try{const data=JSON.parse(await file.text());if(data.records&&data.version===1){if(!Array.isArray(data.records)||data.records.some(v=>!v.id||!v.legalName||!v.result?.checks||!v.runs||!v.country||!v.updatedAt))throw new Error();let added=0;for(const raw of data.records){const v=safeVendor(raw);if(!records.some(r=>r.id===v.id)){records.push(v);added++;}}save();render();toast(`${added} records restored; existing references were preserved.`);}else{const x=data.vendor||data;if(!x||typeof x.legalName!=='string'||typeof x.email!=='string')throw new Error();const allowed=['legalName','contactName','email','country','category','address','taxId','bankName','accountName','routing','account','notes'];draft=Object.fromEntries(allowed.filter(k=>typeof x[k]==='string').map(k=>[k,x[k]]));draft.documents=Array.isArray(x.documents)?x.documents.filter(d=>['bank','tax','compliance'].includes(d.type)).map(d=>({type:d.type,name:String(d.name||d.type+'.json'),legalName:String(d.legalName||''),taxId:String(d.taxId||''),accountLast4:String(d.accountLast4||''),expiresAt:String(d.expiresAt||''),documentType:String(d.documentType||''),unsupported:!!d.unsupported})):[];go('new');toast('Submission imported. Review the inputs before running checks.');}}catch{toast('Invalid JSON. Import a vendor with legalName and email, or a Vendorly backup.');}};input.click();}
document.addEventListener('input',e=>{if(e.target.id==='vendor-search'){query=e.target.value;const pos=e.target.selectionStart;render();const input=$('#vendor-search');input.focus();try{input.setSelectionRange(pos,pos);}catch{}}});
document.addEventListener('change',async e=>{if(e.target.id==='queue-sort'){queueSort=e.target.value;render();}if(e.target.id==='country-filter'){country=e.target.value;render();}if(e.target.dataset.doc&&e.target.files?.[0])await loadFile(e.target.files[0],e.target.dataset.doc);});
document.addEventListener('submit',e=>{if(e.target.id==='sandbox-form'){e.preventDefault();runSandbox(e.target);return;}if(e.target.id==='bank-review-form'){e.preventDefault();confirmBankChange(e.target);return;}if(e.target.id==='submission-form'){e.preventDefault();captureForm();const v=structuredClone(draft);if(!v.bankFingerprint&&!v.account){toast('Enter the bank account number.');return;}runSubmission(v);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){modal=null;render();}if(e.key==='Tab'&&modal){const buttons=[...document.querySelectorAll('.modal button')];if(e.shiftKey&&document.activeElement===buttons[0]){e.preventDefault();buttons.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===buttons.at(-1)){e.preventDefault();buttons[0].focus();}}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
try{const stored=localStorage.getItem(KEY);if(stored){const data=JSON.parse(stored);if(!Array.isArray(data))throw new Error();records=data;}else await seed();}catch{persistent=false;records=[];}
render();

function triageItems(){
 return records.map(vendor=>({vendor,priority:reviewPriority(vendor),expiry:expirySignal(vendor)})).filter(x=>x.priority.rank>0).sort((a,b)=>b.priority.rank-a.priority.rank||new Date(a.vendor.createdAt)-new Date(b.vendor.createdAt));
}
function watchSummary(){
 const watch=records.filter(v=>v.result.status!=='rejected'&&expirySignal(v));
 const holds=records.filter(v=>v.result.checks.some(c=>c.id==='bank-change'&&c.state==='pending'));
 return `<section class="watch-summary"><span class="watch-icon">${icon('clock')}</span><div><strong>${watch.length} compliance document${watch.length===1?'':'s'} to watch</strong><small>Expired or due within 30 days${holds.length?` · ${holds.length} bank-change hold${holds.length===1?'':'s'}`:''}</small></div><button data-go="triage" class="inline-link">View actions →</button></section>`;
}
function actionCenter(){
 const items=triageItems();const expiring=records.filter(v=>v.result.status!=='rejected'&&expirySignal(v));
 const holds=records.filter(v=>v.result.checks.some(c=>c.id==='bank-change'&&c.state==='pending'));
 return pageHead('The right follow-up, first.','Prioritized by blocking findings, bank changes, document dates, and waiting time.',button('New submission','new'))+
 `<div class="metrics">${metric('Priority actions',items.filter(x=>x.priority.tier==='urgent').length,'Payment findings and change holds','shield')}${metric('Documents to watch',expiring.length,'Expired or due within 30 days','clock')}${metric('Bank-change holds',holds.length,'Independent confirmation needed','bank')}${metric('Open actions',items.length,'Each vendor shown once','users')}</div>
 <div class="banner">${icon('info')}Dates are checked when you open this view. Recorded decisions stay unchanged until a new run. Priority is a review order, not a prediction of fraud.</div>
 <section class="panel"><div class="panel-head"><div><h2>Your action queue</h2><p>Urgent findings first, then expiry and waiting time.</p></div><span class="sub">${items.length} vendors</span></div>
 ${items.length?items.map(({vendor:v,priority:p,expiry})=>`<article class="triage-item"><span class="vendor-symbol">${esc(initials(v.legalName))}</span><div class="triage-copy"><button class="vendor-link" data-detail="${esc(v.id)}">${esc(v.legalName)} ↗</button><p>${esc(p.reason)}</p><small>${esc(v.id)}${expiry?` · Compliance: ${esc(expiry.date)}`:''}${v.sample?' · Sample data':''}</small></div><div class="triage-state"><span class="priority-chip ${p.tier}">${p.tier==='urgent'?'Priority':p.tier==='high'?'Time-sensitive':'Review'}</span><small>Last result: ${v.result.status==='pending'?'pending':esc(v.result.status)}</small></div><div class="toolbar"><button class="button secondary small" data-detail="${esc(v.id)}">Review ${icon('arrow')}</button><button class="button text small" data-action="recheck-vendor" data-vendor="${esc(v.id)}">Recheck</button></div></article>`).join(''):'<div class="empty">'+icon('check')+'<h3>Nothing needs attention.</h3><p>No blocking findings, upcoming expiries, or unresolved checks.</p></div>'}</section>
 <section class="panel form-panel" style="margin-top:20px"><h3>How to use this queue</h3><p class="sub" style="margin-top:10px">Review the evidence, correct what is missing, and rerun the checks. A matching replacement bank letter still requires independent confirmation after an approved account changes. You can test a correction in the vendor’s What-if preview before saving it.</p></section>`;
}
function bankGuardUI(v){
 if(!v.result.checks.some(c=>c.id==='bank-change'&&c.state==='pending'))return '';
 return `<div class="bank-hold"><div class="hold-title">${icon('bank')}<h3>Payment account changed after approval</h3></div><p>Contact the vendor through a previously trusted channel. A new email or a matching document alone is not independent confirmation.</p>${bankReviewId===v.id?`
 <form id="bank-review-form"><div class="field"><label for="reviewer-name">Reviewer name</label><input id="reviewer-name" name="reviewer" required minlength="2" maxlength="100" placeholder="Your name"></div><div class="field"><label for="reviewer-note">Verification note</label><textarea id="reviewer-note" name="note" required minlength="20" maxlength="2000" placeholder="Which trusted contact and channel did you use, and what was confirmed?"></textarea></div><label class="checkbox-line"><input type="checkbox" name="confirmed" required>I independently confirmed these details using a previously trusted vendor contact.</label><p class="hint">This records your attestation; no bank API is called. Every other check still needs to pass.</p><div class="toolbar"><button type="submit" class="button small">Record confirmation & recheck</button><button type="button" class="button text small" data-action="cancel-bank-review">Cancel</button></div></form>`:`<button class="button secondary small" data-action="open-bank-review">${icon('shield')}Record independent confirmation</button>`}</div>`;
}
function confirmBankChange(form){
 const v=getCurrent();if(!v)return;
 const values=Object.fromEntries(new FormData(form).entries());
 if(!values.confirmed||String(values.reviewer||'').trim().length<2||String(values.note||'').trim().length<20){toast('Add your name, a verification note of at least 20 characters, and confirm the trusted contact check.');return;}
 if(!v.result.checks.some(c=>c.id==='bank-change'&&c.state==='pending')){toast('This vendor has no open bank-change hold.');return;}
 const candidate=structuredClone(v);
 candidate.bankVerification={vendorId:v.id,reviewer:values.reviewer.trim(),note:values.note.trim(),at:new Date().toISOString(),method:'trusted-channel',fingerprint:v.bankFingerprint,previousFingerprint:approvedBankFor(v),entityKey:entityKey(v)};
 runSubmission(candidate);
}
function sandboxView(v){
 const output=sandbox?.id===v.id?sandbox.preview:null;
 const expiry=v.documents?.find(d=>d.type==='compliance')?.expiresAt||'';
 return `<section class="panel form-panel sandbox-panel"><div class="section-title"><span class="step-num">?</span><div><h3>What would change the decision?</h3><p>Try corrections without saving a vendor or creating a run.</p></div></div>
 <div class="banner">${icon('flask')}This is a hypothetical evaluation using the real rules. It does not change evidence, release holds, or save a new decision.</div>
 <form id="sandbox-form"><div class="fields">${field('accountName','Hypothetical account holder',sandbox?.id===v.id?sandbox.values.accountName:v.accountName)}${field('taxId','Hypothetical tax ID',sandbox?.id===v.id?sandbox.values.taxId:v.taxId)}<div class="field full"><label for="sandbox-expiry">Hypothetical replacement compliance expiry</label><input id="sandbox-expiry" name="expiresAt" type="date" value="${esc(sandbox?.id===v.id?sandbox.values.expiresAt:expiry)}"><small class="hint">Assumes the compliance document contains this date. Missing evidence stays missing.</small></div></div><label class="checkbox-line"><input type="checkbox" name="syncTaxEvidence" ${sandbox?.id===v.id&&sandbox.values.syncTaxEvidence?'checked':''}>Assume replacement tax evidence also contains the corrected tax ID.</label><button type="submit" class="button">${icon('flask')}Preview decision</button></form>
 <div class="preview-result" role="region" aria-live="polite" aria-label="Hypothetical result">${output?`<div class="preview-heading"><div><p class="eyebrow">HYPOTHETICAL OUTCOME</p><h3>Current ${v.result.status} → ${output.result.status}</h3></div>${status(output.result.status)}</div><p>${esc(output.result.summary)}</p>${output.assumptions.map(a=>`<p class="hint">Assumption: ${esc(a)}</p>`).join('')}<div class="delta-list">${output.delta.length?output.delta.map(d=>`<div><strong>${esc(d.label)}</strong><span>${esc(d.before==='not_run'?'Not run':d.before)} → <b class="${d.after}">${esc(d.after)}</b></span></div>`).join(''):'<p>No check outcomes changed.</p>'}</div>${output.result.actions.length?`<div class="remaining-actions"><h3>Still needed</h3><ul>${output.result.actions.map(a=>`<li>${esc(a)}</li>`).join('')}</ul></div>`:''}<p class="hint">Nothing was saved. Use Update & recheck with real supporting evidence to record a decision.</p>`:''}</div></section>`;
}
function runSandbox(form){
 const v=getCurrent();if(!v)return;
 const values=Object.fromEntries(new FormData(form).entries());values.syncTaxEvidence=values.syncTaxEvidence==='on';
 sandbox={id:v.id,values,preview:previewDecision(v,values,records)};render();
 $('.preview-result')?.scrollIntoView?.({behavior:'smooth',block:'nearest'});
}
async function loadScenario(kind){
 draft=fixture(kind);
 if(kind==='bankchange'){
  const base=records.find(v=>v.result.status==='approved'&&v.legalName==='Lumen Creative LLC')||records.find(v=>v.result.status==='approved');
  if(!base){draft=null;toast('Approve a vendor first, or use Run all for an isolated bank-change test.');return;}
  draft=structuredClone(base);draft.account=base.country==='GB'?'42618059':base.country==='IN'?'104261738059':'4261738059';
  if((await hash(bankKey(draft)))===base.bankFingerprint)draft.account=draft.account.slice(0,-1)+(draft.account.endsWith('9')?'8':'9');
  draft.documents=draft.documents.map(d=>d.type==='bank'?{...d,accountLast4:draft.account.slice(-4)}:d);
  draft.notes='Scenario: the approved vendor requests a new bank account. A matching bank document does not remove the independent contact hold.';
 }
 if(kind==='duplicate'){
  const base=records.find(v=>v.country==='US');
  if(!base){draft=null;toast('This editable example needs an existing US vendor. Use Run all for an isolated duplicate test.');return;}
  draft.taxId=base.taxId;draft.documents=draft.documents.map(d=>d.type==='tax'?{...d,taxId:base.taxId}:d);
 }
 if(kind==='collision'){
  const base=records.find(v=>v.legalName==='Lumen Creative LLC');
  if(!base||base.bankFingerprint!==await hash(bankKey(draft))){draft=null;toast('The editable collision needs the original Lumen sample account. Run all uses an isolated baseline.');return;}
 }
 go('new');if(route()==='new')render();toast('Editable example loaded. Previous workspace records may affect the result.');
}
function suiteView(){
 if(!suite)return '';
 const rows=suite.rows,passed=rows.filter(r=>r.pass).length;
 return `<section class="panel suite-panel" aria-live="polite"><div class="panel-head"><div><h2>${suite.running?'Executing checks…':`${passed} of ${scenarios.length} scenarios match expectations`}</h2><p>${rows.length}/${scenarios.length} complete · ${POLICY_VERSION} · isolated sample history</p></div>${!suite.running?button('Export results','export-suite','down',true):'<span class="status running">Running</span>'}</div><div class="run-progress">${scenarios.map((_,i)=>`<i class="${i<rows.length?'done':''}"></i>`).join('')}</div><div class="suite-table table-wrap"><table><thead><tr><th>Scenario</th><th>Expected</th><th>Actual</th><th>Test result</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.title)}</strong><small class="suite-finding">${esc(r.error||r.findings.map(c=>c.label).join(' · ')||'All configured checks passed')}</small></td><td>${status(r.expected)}</td><td>${r.actual==='error'?'Error':status(r.actual)}</td><td><span class="suite-outcome ${r.pass?'pass':'fail'}">${r.pass?'✓ Passed':'× Failed'}</span></td></tr>`).join('')}</tbody></table></div></section>`;
}
async function suiteInput(kind){
 const vendor=fixture(kind);const history=[];
 if(['collision','bankchange','duplicate'].includes(kind)){
  const baseline=fixture();baseline.id=kind==='bankchange'?vendor.id:'VND-SUITE-BASE';
  if(kind==='collision'){baseline.legalName='Lumen Creative LLC';baseline.accountName=baseline.legalName;baseline.account='6118342096';baseline.documents=baseline.documents.map(d=>({...d,legalName:baseline.legalName,accountLast4:'2096'}));}
  baseline.bankFingerprint=await hash(bankKey(baseline));baseline.accountLast4=baseline.account.slice(-4);baseline.result=evaluate(baseline,[]);baseline.approvedBankFingerprint=baseline.bankFingerprint;history.push(baseline);
 }
 vendor.bankFingerprint=await hash(bankKey(vendor));vendor.accountLast4=vendor.account.slice(-4);return {vendor,history};
}
async function runScenarioSuite(){
 if(suite?.running)return;
 suite={running:true,policy:POLICY_VERSION,startedAt:new Date().toISOString(),rows:[]};render();
 for(const [kind,title,,expected,,,expectedFindings] of scenarios){
  const started=performance.now();
  try{
   const {vendor,history}=await suiteInput(kind);const result=evaluate(vendor,history);const findings=result.checks.filter(c=>c.state!=='pass');
   suite.rows.push({kind,title,expected,actual:result.status,pass:result.status===expected&&expectedFindings.every(id=>findings.some(c=>c.id===id)),findings,checksPassed:result.passed,totalChecks:result.total,durationMs:Math.round(performance.now()-started)});
  }catch(error){suite.rows.push({kind,title,expected,actual:'error',pass:false,findings:[],error:String(error.message)});}
  if(route()==='lab')render();await new Promise(requestAnimationFrame);
 }
 suite.running=false;suite.completedAt=new Date().toISOString();if(route()==='lab')render();toast(`Scenario suite complete: ${suite.rows.filter(x=>x.pass).length}/${scenarios.length} passed. Workspace records were unchanged.`);
}
